 try{const preferences=JSON.parse(localStorage.getItem('six-realms-ui-v08')||'{}');ui.sound=preferences.sound!==false;ui.ambience=preferences.ambience!==false;ui.volume=Number.isFinite(preferences.volume)?Math.max(0,Math.min(1,preferences.volume)):.45;ui.fastAI=preferences.fastAI!==false;ui.motionMode=['standard','fast','reduced'].includes(preferences.motionMode)?preferences.motionMode:'standard';}catch{}
 const FX=GameFX;try{const p=JSON.parse(localStorage.getItem('six-realms-ui-v08')||'{}'),legacy=JSON.parse(localStorage.getItem('six-realms-fx-v0.8')||'{}');if(!Object.hasOwn(p,'sound')&&legacy.soundEnabled===false)ui.sound=false;if(!Object.hasOwn(p,'volume')&&Number.isFinite(legacy.volume))ui.volume=Math.max(0,Math.min(1,legacy.volume));if(!Object.hasOwn(p,'ambience')&&legacy.ambienceEnabled===false)ui.ambience=false;}catch{}FX.setSoundEnabled(ui.sound);FX.setVolume(ui.volume);FX.setAmbienceEnabled?.(ui.ambience);
 function savePreferences(){try{localStorage.setItem('six-realms-ui-v08',JSON.stringify({sound:ui.sound,ambience:ui.ambience,volume:ui.volume,fastAI:ui.fastAI,motionMode:ui.motionMode}));}catch{}}
 const settings={size:'S',source:'fixed',playerCount:2,seed:'',landscapeId:'balanced_coast',victoryMode:'capture_hq',teams:'ffa',fog:true,difficulty:'standard',controllers:['local_human','ai','ai','ai','ai','ai'],names:['指挥官 1','指挥官 2','指挥官 3','指挥官 4','指挥官 5','指挥官 6']};
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),btn=(text,action,cls='',disabled='',tip='')=>`<button ${disabled?'disabled':''} class="${cls}" data-action="${action}" ${disabled||tip?`data-tooltip="${esc(disabled||tip)}"`:''}>${text}</button>`;
 function commandButton(text,command,reason='',cls='',tip=''){return `<button class="${cls}" data-cmd="${esc(JSON.stringify(command))}" ${reason?'disabled':''} ${reason||tip?`data-tooltip="${esc(reason||tip)}"`:''}>${text}</button>`;}
 const opt=(value,label,current)=>`<option value="${value}" ${value===String(current)?'selected':''}>${label}</option>`,goalName=v=>v==='capture_hq'?'占领原始总部':'接管全部登记建筑',sourceName=v=>({fixed:'固定地图',random:'随机地图',fixed_fallback:'固定备用地图',campaign:'剧情地图',standard:'标准战场',sandbox:'规则测试场'}[v]||v);
 function difficultyOptions(current){return (GameAI.difficulties||[{id:'easy',name:'简单'},{id:'standard',name:'标准'},{id:'hard',name:'困难'},{id:'hell',name:'地狱'}]).map(d=>opt(d.id,d.name,current)).join('');}
 function difficultyName(value){return ({easy:'简单',training:'简单',standard:'标准',hard:'困难',challenge:'困难',hell:'地狱'})[value]||'标准';}
 function difficultyGuide(){return `<details class="difficulty-guide"><summary>四档人机难度说明</summary><div>${GameAI.difficulties.map(d=>`<article><strong>${esc(d.name)}</strong><p>${esc(d.description)}</p></article>`).join('')}</div><small>难度影响 AI 控制方；困难与地狱都遵守自身视野和行动规则。</small></details>`;}
 function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3800);}
