 function xy(c){return {x:Math.sqrt(3)*44*(c.q+c.r/2),y:66*c.r};}
 let lastSceneUpdate=-Infinity;
 function updateSoundScene(force=false){
  if(!FX.setScene)return;const audioPlace=ui.view!=='game'?'menu':ui.dialog||ui.game?.story?.queue.length?'briefing':'battle';window.GameAudio?.setScene({active:!document.hidden&&!ui.paused&&!ui.game?.handoffRequired,place:audioPlace,chapter:ui.game?.mission?.id,result:ui.view==='game'&&ui.game?.result?(!ui.game.result.winner?'draw':ui.game.result.winningPlayers?.includes(viewer())?'win':'loss'):null});
  const s=ui.game,active=ui.view==='game'&&s&&!document.hidden&&!ui.paused&&!ui.dialog&&!s.handoffRequired&&!s.result&&!s.story?.queue.length;
  if(!active){FX.setScene({terrain:'plain',active:false});return;}
  const now=performance.now();if(!force&&now-lastSceneUpdate<700)return;lastSceneUpdate=now;
  let terrain='plain',distance=Infinity;const id=viewer();
  for(const c of s.cells){if(!G.visible(s,id,c))continue;const p=xy(c),next=(p.x-ui.camera.x)**2+(p.y-ui.camera.y)**2;if(next<distance){distance=next;terrain=c.terrain;}}
  FX.setScene({terrain,profile:s.mission?.id==='C05'?'crystal':undefined,active:true});
 }
 function bounds(cells){const points=cells.map(xy),xs=points.map(p=>p.x),ys=points.map(p=>p.y);return {x:Math.min(...xs)-50,y:Math.min(...ys)-50,w:Math.max(...xs)-Math.min(...xs)+100,h:Math.max(...ys)-Math.min(...ys)+100};}
